class RoutesCommand(click.Command):
    """The ``routes`` command. The corresponding test is in
    :mod:`tests.test_cli`.
    """

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._split_blueprint_path = _split_blueprint_path

    def show_route(self, rule, all_methods=False):
        methods = ",".join(sorted(rule.methods - {"HEAD", "OPTIONS"}))
        if not all_methods:
            methods = ",".join(sorted(rule.methods - {"HEAD", "OPTIONS"}))
        else:
            methods = ",".join(sorted(rule.methods))
        endpoint = rule.endpoint
        rule_str = rule.rule
        return endpoint, methods, rule_str

    def get_routes_map(self, app, all_methods=False):
        rules = []
        for rule in app.url_map.iter_rules():
            endpoint, methods, rule_str = self.show_route(rule, all_methods)
            rules.append((endpoint, methods, rule_str))
        return rules

    def print_routes(self, app, all_methods=False, sort="endpoint"):
        rules = self.get_routes_map(app, all_methods)
        if sort == "endpoint":
            rules.sort(key=lambda x: x[0])
        elif sort == "methods":
            rules.sort(key=lambda x: x[1])
        elif sort == "rule":
            rules.sort(key=lambda x: x[2])
        elif sort == "match":
            rules.sort(key=lambda x: app.url_map._rules.index(x[0]))
        else:
            raise click.BadParameter(f"Invalid sort option: {sort}")

        if not rules:
            click.echo("No routes were registered.")
            return

        headers = ("Endpoint", "Methods", "Rule")
        widths = [len(h) for h in headers]
        for row in rules:
            for i, cell in enumerate(row):
                widths[i] = max(widths[i], len(cell))

        click.echo(" ".join(h.ljust(w) for h, w in zip(headers, widths)))
        click.echo("-" * (sum(widths) + len(headers) - 1))
        for row in rules:
            click.echo(" ".join(c.ljust(w) for c, w in zip(row, widths)))

    def get_usage(self, ctx):
        formatter = ctx.make_formatter()
        self.format_usage(ctx, formatter)
        return formatter.getvalue().rstrip("\n")

    def get_help(self, ctx):
        formatter = ctx.make_formatter()
        self.format_help(ctx, formatter)
        return formatter.getvalue().rstrip("\n")

    def invoke(self, ctx):
        app = ctx.ensure_object(ScriptInfo).load_app()
        all_methods = ctx.params.get("all_methods", False)
        sort = ctx.params.get("sort", "endpoint")
        self.print_routes(app, all_methods, sort)
